(function(){"use strict";const D=window.DFData;const B=window.DFBackups;if(!D||!B||!B.readJson)return;const{BOOKS,DBS,EYE_DB,EYE_STATE,existing,readJson,restoreJson,otherBook,noPart}=B;const ls={get(k){try{return localStorage.getItem(k)}catch(e){return null}},set(k,v){try{localStorage.setItem(k,v)}catch(e){}}};async function makeBackup(onProgress,only){if(only){const b=BOOKS[only];return D.zipBackup({app:only,databases:b.dbs,local:b.local,extra:b.book?{book:ls.get(b.book)||``}:{},filename:`${only}-backup-${D.todayStr()}.zip`,onProgress})}const have=await existing();const eye=!!ls.get(EYE_STATE);const dbs=DBS.map(n=>n.db).filter(n=>!have||have.has(n));if(eye)dbs.push(EYE_DB);if(!dbs.length)return null;return D.zipBackup({app:`documenting-fictions`,kind:`suite`,databases:dbs,local:[...eye?[EYE_STATE]:[],...DBS.filter(n=>n.book).map(n=>n.book)],filename:`documenting-fictions-backup-${D.todayStr()}.zip`,onProgress})}const eyeCheck=(needed,app)=>async local=>{const st=await local(EYE_STATE);if(st==null){if(needed)throw noPart(app);return}let ok=false;try{ok=Array.isArray(JSON.parse(st).shoots)}catch(e){}if(!ok)throw new Error(`The Eye's part of that file isn't right. Nothing was changed.`)};async function putEyeState(r){const st=await r.local(EYE_STATE);if(st==null)return;localStorage.setItem(EYE_STATE,st);const p=JSON.parse(st).presentation;if(p&&p.color)ls.set(`df-app-color`,p.color)}async function restoreZip(files,onProgress,only){if(only){const b=BOOKS[only];const r=await D.restoreZip(files,{databases:b.dbs,onProgress,check:only===`the-eye`?eyeCheck(true,only):undefined});const book=b.book&&(r.extra&&r.extra.book||await r.local(b.book));if(book)ls.set(b.book,book);if(only===`the-eye`)await putEyeState(r);return}const r=await D.restoreZip(files,{kind:`suite`,databases:[...DBS.map(n=>n.db),EYE_DB],onProgress,check:eyeCheck(false)});for(const n of DBS){const book=n.book?await r.local(n.book):null;if(book)ls.set(n.book,book)}await putEyeState(r)}async function whatsIn(files){const list=Array.isArray(files)?files:[files];if(!list.length)throw new Error(`That file isn't a Documenting Fictions backup.`);let got;if(await D.isZipFile(list[0])){const m=await D.backupManifest(list);got=m.kind===`suite`?{all:true}:{app:m.app}}else{const{all,app}=await readJson(list[0]);got=all?{all:true}:{app}}if(!got.all&&!BOOKS[got.app])throw otherBook();return got}async function restore(files,{only,onProgress=()=>{}}={}){const list=Array.isArray(files)?files:[files];if(list.length&&await D.isZipFile(list[0]))return restoreZip(list,onProgress,only);return restoreJson(list[0],only)}Object.assign(B,{makeBackup,restoreZip,whatsIn,restore})})();
