(function(){"use strict";const D=window.DFData;const B=window.DFBackups;const S=window.DFBackupSheet;if(!D||!B||!B.restore||!S)return;const{BOOKS}=B;const PICK=`.zip,application/zip,.json,application/json`;function sorry(message){const s=S.frame(`Restore`,`<p class="dfb-text"></p><button type="button" class="dfb-btn quiet" data-close>Close</button>`);s.el.querySelector(`.dfb-text`).textContent=message||`That backup couldn't be restored.`}function confirm(files,{only=null,done=null}={}){const name=only?BOOKS[only].name:`all four`;const what=only?`Everything in ${name} on this device is swapped for what's in the file. The other notebooks stay as they are.`:`Everything in Ref, The Eye, Layouts and Rounds on this device is swapped for what's in the file.`;return new Promise(resolve=>{let busy=false;const s=S.frame(`Restore ${name}?`,`<p class="dfb-text">${what} This can't be undone, so back up first if you might want today's back.</p>
        <button type="button" class="dfb-btn danger" data-yes>Restore</button>
        <button type="button" class="dfb-btn quiet" data-close>Cancel</button>
        <p class="dfb-note" hidden></p>`,()=>{if(!busy)resolve(false)});const yes=s.el.querySelector(`[data-yes]`);const note=s.el.querySelector(`.dfb-note`);const say=text=>{note.textContent=text;note.hidden=false};yes.addEventListener(`click`,async()=>{busy=true;yes.disabled=true;yes.textContent=`Restoring`;try{await B.restore(files,{only,onProgress:f=>{yes.textContent=`Restoring, ${Math.floor(f*100)}%`}});yes.textContent=`Restored`;say(only?`${name} is back as it was in the file.`:`All four are back as they were in the file.`);resolve(true);setTimeout(()=>{if(done){s.close();done()}else location.reload()},900)}catch(err){console.error(err);busy=false;yes.disabled=false;yes.textContent=`Restore`;say(err.message||`That backup couldn't be restored.`)}})})}async function fromShelf(){const files=await D.pickFiles(PICK);if(!files.length)return false;let got;try{got=await B.whatsIn(files)}catch(err){sorry(err.message);return false}return confirm(files,{only:got.all?null:got.app})}async function which(files,here){let got=null;try{got=await B.whatsIn(files)}catch(e){}if(!got||!got.all)return{files};const json=!await D.isZipFile(files[0]);const just=async()=>({files:json?[await B.partFile(files[0],here)]:files});if(!D.inSuite())return just();return new Promise(resolve=>{let picked=false;const s=S.frame(`Restore`,`<p class="dfb-text">This backup has all four notebooks.</p>
        <button type="button" class="dfb-btn" data-just>Just ${BOOKS[here].name}</button>
        <button type="button" class="dfb-btn quiet" data-all>All four</button>`,()=>{if(!picked)resolve(null)});s.el.addEventListener(`click`,async e=>{const b=e.target.closest(`[data-just], [data-all]`);if(!b)return;picked=true;s.close();resolve(b.hasAttribute(`data-all`)?{all:true}:await just())})})}window.DFRestore={PICK,fromShelf,which,confirm}})();
